{
  "case_id": "C03",
  "audience": "School governors and parents",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Why absence matters",
      "narration": "Respiratory illness is the biggest single cause of pupil absence in our primary schools, accounting for around half of all coded absence days across the winter.",
      "on_screen": "Title: Do classroom air cleaners cut pupil absence? Beneath it: respiratory illness = about half of coded winter absence days.",
      "claim_refs": ["SYN-C03/Background"]
    },
    {
      "beat": "What was done",
      "narration": "Twenty-two classrooms in one local authority were each given two portable HEPA air cleaners. Eighteen other classrooms in the same authority carried on as normal. Absence was compared over an eleven-week winter term against the same term the year before.",
      "on_screen": "Two columns: 22 classrooms with 2 HEPA units each; 18 classrooms without. Footer: 11-week winter term, compared with the same term last year.",
      "claim_refs": ["SYN-C03/Abstract", "SYN-C03/Methods", "SYN-C03/Statistical analysis"]
    },
    {
      "beat": "What was found",
      "narration": "In classrooms with the units, respiratory absence fell from four point nine to three point six percent of pupil-days. In classrooms without, it fell from four point seven to four point four. That is a difference of about one percentage point, though the range of uncertainty runs from nearly two points down to almost nothing.",
      "on_screen": "Bar chart, before and after by arm: 4.9 to 3.6 percent with units; 4.7 to 4.4 percent without. Callout: difference minus 1.0 percentage points, 95% confidence interval minus 1.9 to minus 0.1.",
      "claim_refs": ["SYN-C03/Abstract", "SYN-C03/Results"]
    },
    {
      "beat": "How much weight to put on it",
      "narration": "Some caution is needed. Classrooms were not chosen at random, but by available floor space, and ventilation already differed between the two groups. Staff could see the units. And absence came from the school's own respiratory code, not from any confirmed diagnosis.",
      "on_screen": "Checklist headed Read with care: not randomised, allocated by floor space; ventilation differed at baseline; unblinded; outcome is an administrative code, not a tested diagnosis.",
      "claim_refs": ["SYN-C03/Study design", "SYN-C03/Methods", "SYN-C03/Limitations"]
    },
    {
      "beat": "What it means for governors",
      "narration": "So this is an encouraging signal, not proof, from a single term in a single authority. If your school is considering air cleaners, weigh the purchase and running costs against a reduction of roughly this size, and treat any wider rollout as something still worth evaluating.",
      "on_screen": "Closing card: Encouraging, not conclusive. One term, one authority. Weigh costs against the observed reduction; evaluate wider rollout.",
      "claim_refs": ["SYN-C03/Discussion", "SYN-C03/Conclusion", "SYN-C03/Methods"]
    }
  ]
}
